class TextReaderAdapter:              # target protocol: read() -> str
    def __init__(self, adaptee: BinarySource) -> None:
        self._adaptee = adaptee

    def read(self, size: int = -1) -> str:
        return self._adaptee.read_bytes(size).decode('utf-8')

    # __getattr__ can forward everything else (but never dunders):
    def __getattr__(self, name):
        return getattr(self._adaptee, name)

